#!/usr/bin/env node
/**
 * add-images.mjs
 * Updates the bar detail page to use actual images once generated by Nano Banana.
 * 
 * Place all images from Nano Banana in: public/images/<slug>.jpg
 * Then run: node scripts/add-images.mjs
 * 
 * The script checks which images exist and exports a manifest.
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, "../data/bars.json");
const IMAGES_DIR = path.join(__dirname, "../public/images");
const MANIFEST_FILE = path.join(__dirname, "../data/image-manifest.json");

const bars = JSON.parse(fs.readFileSync(DATA_FILE, "utf8"));

const manifest = {};
let found = 0;
let missing = 0;

for (const bar of bars) {
  const jpgPath = path.join(IMAGES_DIR, `${bar.slug}.jpg`);
  const pngPath = path.join(IMAGES_DIR, `${bar.slug}.png`);
  const webpPath = path.join(IMAGES_DIR, `${bar.slug}.webp`);

  if (fs.existsSync(jpgPath)) {
    manifest[bar.slug] = `/images/${bar.slug}.jpg`;
    found++;
  } else if (fs.existsSync(pngPath)) {
    manifest[bar.slug] = `/images/${bar.slug}.png`;
    found++;
  } else if (fs.existsSync(webpPath)) {
    manifest[bar.slug] = `/images/${bar.slug}.webp`;
    found++;
  } else {
    manifest[bar.slug] = null;
    missing++;
  }
}

fs.writeFileSync(MANIFEST_FILE, JSON.stringify(manifest, null, 2));

console.log(`\n🖼  Image Manifest`);
console.log(`✅ Found: ${found} images`);
console.log(`❌ Missing: ${missing} images`);
console.log(`📁 Manifest saved to data/image-manifest.json\n`);

if (missing > 0) {
  console.log("Missing images for:");
  Object.entries(manifest)
    .filter(([, v]) => !v)
    .slice(0, 20)
    .forEach(([slug]) => console.log(`  - ${slug}`));
  if (missing > 20) console.log(`  ... and ${missing - 20} more`);
}
